package org.brightstats.stats;

import java.util.*;
import java.util.function.IntConsumer;
import org.apache.commons.math3.linear.*;

/** Gaussian mixtures of acyclic structural regressions on fixed observed/composite scores. */
public final class FiniteMixture {
    private FiniteMixture(){}
    public enum Initialization {RANDOM_SIMPLEX,REFERENCE_STICK_1000}
    public enum Stopping {OBSERVED_LOG_LIKELIHOOD,EXPECTED_COMPLETE_LOG_LIKELIHOOD}
    public record Options(int segments,int repetitions,int maxIterations,double tolerance,long seed,boolean intercept,double varianceFloor,double minimumMass,Initialization initialization,Stopping stopping){
        public Options{Objects.requireNonNull(initialization);Objects.requireNonNull(stopping);if(segments<1||segments>100||repetitions<1||repetitions>1000||maxIterations<1||maxIterations>100000||!Double.isFinite(tolerance)||tolerance<=0||tolerance>=1||!Double.isFinite(varianceFloor)||varianceFloor<=0||!Double.isFinite(minimumMass)||minimumMass<=0)throw new IllegalArgumentException("Invalid mixture segments, repetitions, iteration/tolerance, variance floor or minimum class mass.");}
        public static Options defaults(){return new Options(2,10,5000,1e-7,ReferenceResampling.DEFAULT_SEED,false,.001,2,Initialization.RANDOM_SIMPLEX,Stopping.OBSERVED_LOG_LIKELIHOOD);}
    }
    public record Equation(int response,int[] parents,double intercept,double[] coefficients,double variance,double rawVariance,double weightedResidualSum,double centeredRSquared,double globalCenteredRSquared,boolean varianceConstrained){public Equation{parents=parents.clone();coefficients=coefficients.clone();}@Override public int[] parents(){return parents.clone();}@Override public double[] coefficients(){return coefficients.clone();}}
    public record Segment(int index,double proportion,double posteriorProportion,double fittedMass,double posteriorKishSize,int hardCount,List<Equation> equations){public Segment{equations=List.copyOf(equations);}}
    public record Iteration(int iteration,double logLikelihood,double expectedCompleteLogLikelihood,double likelihoodChange,double expectedChange,double smallestFittedMass,int activeVarianceFloors){}
    public record Start(int index,long seed,boolean converged,int iterations,double logLikelihood,String failure){}
    public record Criteria(int parameters,int referenceParameters,double aic,double aic3,double aic4,double bic,double caic,double hq,double mdl5,double referenceAic,double referenceBic,double entropy,double normalizedEntropy,double nonFuzzyIndex,double likelihoodNormalizedEntropy,double referenceNec,double baselineLogLikelihood,boolean convergedInteriorCandidate){}
    public record Result(Options options,int observations,List<String> names,List<PlsSem.Edge> edges,int bestStart,boolean converged,double logLikelihood,List<Segment> segments,double[][] probabilities,int[] assignments,int[] finalToInitial,double[][] initialProbabilities,List<Iteration> trace,List<Start> starts,Criteria criteria,List<String> warnings){
        public Result{names=List.copyOf(names);edges=List.copyOf(edges);segments=List.copyOf(segments);probabilities=Matrices.copy(probabilities);assignments=assignments.clone();finalToInitial=finalToInitial.clone();initialProbabilities=Matrices.copy(initialProbabilities);trace=List.copyOf(trace);starts=List.copyOf(starts);warnings=List.copyOf(warnings);}@Override public double[][] probabilities(){return Matrices.copy(probabilities);}@Override public int[] assignments(){return assignments.clone();}@Override public int[] finalToInitial(){return finalToInitial.clone();}@Override public double[][] initialProbabilities(){return Matrices.copy(initialProbabilities);}
    }
    private record ModelState(List<List<Equation>> equations,double[] proportions,double[] masses){}
    private record Expectation(double logLikelihood,double expectedComplete,double[][] probabilities){}
    private record Candidate(int start,boolean converged,ModelState model,Expectation expectation,double[][] initial,List<Iteration> trace){}
    static final class Work {
        final double[][] data;final int n,p;final List<String> names;final List<PlsSem.Edge> edges;final List<int[]> parents=new ArrayList<>();final List<Integer> responses=new ArrayList<>();final double[] means;final Options options;final int coefficients;
        Work(double[][] source,List<String> supplied,List<PlsSem.Edge> suppliedEdges,Options options){p=Matrices.width(source,3);data=Matrices.copy(source);n=data.length;names=List.copyOf(supplied);edges=List.copyOf(suppliedEdges);this.options=options;if(names.size()!=p||new HashSet<>(names).size()!=p||names.stream().anyMatch(name->name==null||name.isBlank())||edges.isEmpty())throw new IllegalArgumentException("Mixture names and nonempty structural paths are required.");if((long)n*options.segments()>10000000L||n<options.segments()*options.minimumMass())throw new IllegalArgumentException("Mixture class/membership size exceeds the data or current memory limit.");List<List<Integer>> incoming=new ArrayList<>(),children=new ArrayList<>();for(int j=0;j<p;j++){incoming.add(new ArrayList<>());children.add(new ArrayList<>());}Set<String> seen=new HashSet<>();for(var edge:edges){if(edge.source()<0||edge.source()>=p||edge.target()<0||edge.target()>=p||edge.source()==edge.target()||!seen.add(edge.source()+":"+edge.target()))throw new IllegalArgumentException("Mixture paths must be unique available variable pairs.");incoming.get(edge.target()).add(edge.source());children.get(edge.source()).add(edge.target());}int[] degrees=new int[p];ArrayDeque<Integer> queue=new ArrayDeque<>();for(int j=0;j<p;j++){degrees[j]=incoming.get(j).size();if(degrees[j]==0)queue.add(j);else{responses.add(j);parents.add(incoming.get(j).stream().mapToInt(Integer::intValue).toArray());}}int visited=0;while(!queue.isEmpty()){int node=queue.remove();visited++;for(int child:children.get(node))if(--degrees[child]==0)queue.add(child);}if(visited!=p)throw new IllegalArgumentException("Mixture structural paths must be acyclic.");coefficients=edges.size()+(options.intercept()?responses.size():0);if((long)n*options.segments()*coefficients>50000000L)throw new IllegalArgumentException("Mixture weighted-regression work exceeds the current size limit.");means=new double[p];for(int j=0;j<p;j++)for(int i=0;i<n;i++)means[j]+=(data[i][j]-means[j])/(i+1);for(var predictors:parents)if(n<=predictors.length+(options.intercept()?1:0))throw new IllegalArgumentException("Too few observations for a mixture equation.");}
        ModelState maximize(double[][] membership){int k=options.segments();double[] masses=new double[k],proportions=new double[k];for(double[] row:membership)for(int segment=0;segment<k;segment++)masses[segment]+=row[segment];List<List<Equation>> equations=new ArrayList<>();for(int segment=0;segment<k;segment++){
            Matrices.interrupted();double mass=masses[segment];if(!Double.isFinite(mass)||mass<options.minimumMass())throw new IllegalArgumentException("Mixture class mass below configured minimum.");proportions[segment]=mass/n;List<Equation> current=new ArrayList<>();for(int equation=0;equation<responses.size();equation++){int response=responses.get(equation);int[] predictors=parents.get(equation);int offset=options.intercept()?1:0,q=predictors.length+offset;double[][] x=new double[n][q];double[] y=new double[n];for(int i=0;i<n;i++){if((i&255)==0)Matrices.interrupted();double root=Math.sqrt(membership[i][segment]);if(offset==1)x[i][0]=root;for(int j=0;j<predictors.length;j++)x[i][j+offset]=root*data[i][predictors[j]];y[i]=root*data[i][response];}var solver=new QRDecomposition(new Array2DRowRealMatrix(x,false),1e-12).getSolver();if(!solver.isNonSingular())throw new IllegalArgumentException("Mixture weighted design is rank deficient.");double[] beta=solver.solve(new ArrayRealVector(y,false)).toArray();if(!Arrays.stream(beta).allMatch(Double::isFinite))throw new IllegalArgumentException("Mixture coefficient exceeded finite range.");double intercept=offset==1?beta[0]:0;double[] coefficients=Arrays.copyOfRange(beta,offset,beta.length);double mean=0;for(int i=0;i<n;i++)mean+=membership[i][segment]*data[i][response]/mass;double residual=0,centered=0,global=0;for(int i=0;i<n;i++){double fitted=intercept;for(int j=0;j<predictors.length;j++)fitted+=coefficients[j]*data[i][predictors[j]];double weight=membership[i][segment];residual+=weight*Math.pow(data[i][response]-fitted,2);centered+=weight*Math.pow(data[i][response]-mean,2);global+=weight*Math.pow(data[i][response]-means[response],2);}double raw=residual/mass,variance=Math.max(raw,options.varianceFloor());if(!Double.isFinite(variance)||!Double.isFinite(residual))throw new IllegalArgumentException("Mixture variance exceeded finite range.");current.add(new Equation(response,predictors,intercept,coefficients,variance,raw,residual,centered>0?1-residual/centered:Double.NaN,global>0?1-residual/global:Double.NaN,raw<=options.varianceFloor()));}equations.add(List.copyOf(current));}return new ModelState(List.copyOf(equations),proportions,masses);}
        Expectation expectation(ModelState model,double[][] oldMembership){int k=options.segments();double[][] membership=new double[n][k];double likelihood=0,expected=0;double[] logDensity=new double[k];for(int i=0;i<n;i++){if((i&255)==0)Matrices.interrupted();double highest=Double.NEGATIVE_INFINITY;for(int segment=0;segment<k;segment++){double value=Math.log(model.proportions()[segment]);for(var equation:model.equations().get(segment)){double fitted=equation.intercept();for(int j=0;j<equation.parents.length;j++)fitted+=equation.coefficients[j]*data[i][equation.parents[j]];double error=data[i][equation.response()]-fitted;value-=.5*(Math.log(2*Math.PI)+Math.log(equation.variance())+error*error/equation.variance());}if(!Double.isFinite(value))throw new IllegalArgumentException("Mixture log density exceeded finite range.");logDensity[segment]=value;highest=Math.max(highest,value);if(oldMembership!=null&&oldMembership[i][segment]>0)expected+=oldMembership[i][segment]*value;}double total=0;for(int segment=0;segment<k;segment++)total+=Math.exp(logDensity[segment]-highest);double logTotal=highest+Math.log(total);likelihood+=logTotal;for(int segment=0;segment<k;segment++)membership[i][segment]=Math.exp(logDensity[segment]-highest)/total;}if(!Double.isFinite(likelihood)||!Double.isFinite(expected))throw new IllegalArgumentException("Mixture likelihood exceeded finite range.");return new Expectation(likelihood,expected,membership);}
        Candidate run(int index,long seed){double[][] initial=initialize(n,options.segments(),seed,options.initialization()),membership=initial;List<Iteration> trace=new ArrayList<>();double lastLikelihood=Double.NaN,lastExpected=Double.NaN;ModelState model=null;Expectation e=null;boolean converged=false;for(int iteration=1;iteration<=options.maxIterations();iteration++){Matrices.interrupted();model=maximize(membership);e=expectation(model,membership);double delta=e.logLikelihood()-lastLikelihood,qDelta=e.expectedComplete()-lastExpected;if(Double.isFinite(lastLikelihood)&&delta<-1e-9*Math.max(1,Math.abs(lastLikelihood)))throw new IllegalArgumentException("Mixture observed likelihood decreased beyond numerical tolerance.");double minimum=Arrays.stream(model.masses()).min().orElseThrow();int floors=model.equations().stream().mapToInt(values->(int)values.stream().filter(Equation::varianceConstrained).count()).sum();trace.add(new Iteration(iteration,e.logLikelihood(),e.expectedComplete(),delta,qDelta,minimum,floors));double criterion=options.stopping()==Stopping.OBSERVED_LOG_LIKELIHOOD?delta:qDelta;if(iteration>1&&Math.abs(criterion)<=options.tolerance()){converged=true;break;}lastLikelihood=e.logLikelihood();lastExpected=e.expectedComplete();membership=e.probabilities();}return new Candidate(index,converged,model,e,initial,List.copyOf(trace));}
    }
    public static double[][] initialize(int n,int segments,long seed,Initialization type){if(n<1||segments<1||(long)n*segments>10000000L)throw new IllegalArgumentException("Positive bounded mixture initialization dimensions required.");Objects.requireNonNull(type);Random random=new Random(seed);double[][] result=new double[n][segments];for(int i=0;i<n;i++){if((i&255)==0)Matrices.interrupted();if(type==Initialization.REFERENCE_STICK_1000){int remaining=1000;for(int segment=0;segment<segments-1;segment++){int selected=random.nextInt(remaining);result[i][segment]=selected/1000.0;remaining-=selected;}result[i][segments-1]=remaining/1000.0;}else{double total=0;for(int segment=0;segment<segments;segment++){result[i][segment]=-Math.log(Math.max(Double.MIN_NORMAL,random.nextDouble()));total+=result[i][segment];}for(int segment=0;segment<segments;segment++)result[i][segment]/=total;}}return result;}
    public static Result fit(double[][] scores,List<String> names,List<PlsSem.Edge> edges,Options options,IntConsumer progress){
        Work work=new Work(scores,names,edges,options);long[] seeds=ReferenceResampling.seeds(options.seed(),options.repetitions());List<Start> starts=new ArrayList<>();Candidate best=null;for(int index=0;index<options.repetitions();index++){Matrices.interrupted();try{var candidate=work.run(index,seeds[index]);starts.add(new Start(index,seeds[index],candidate.converged(),candidate.trace().size(),candidate.expectation().logLikelihood(),null));if(best==null||candidate.converged()&&!best.converged()||candidate.converged()==best.converged()&&candidate.expectation().logLikelihood()>best.expectation().logLikelihood())best=candidate;}catch(IllegalArgumentException|ArithmeticException problem){starts.add(new Start(index,seeds[index],false,-1,Double.NaN,problem.getMessage()));}if(progress!=null)progress.accept(index+1);}if(best==null)throw new IllegalArgumentException("Every mixture start failed: "+starts.stream().map(Start::failure).toList());int k=options.segments(),n=work.n;Candidate chosen=best;Integer[] order=java.util.stream.IntStream.range(0,k).boxed().sorted(Comparator.<Integer>comparingDouble(segment->-chosen.model().proportions()[segment]).thenComparingInt(Integer::intValue)).toArray(Integer[]::new);double[][] posterior=new double[n][k];for(int i=0;i<n;i++)for(int segment=0;segment<k;segment++)posterior[i][segment]=best.expectation().probabilities()[i][order[segment]];int[] assignments=new int[n],counts=new int[k];for(int i=0;i<n;i++){for(int segment=1;segment<k;segment++)if(posterior[i][segment]>posterior[i][assignments[i]])assignments[i]=segment;counts[assignments[i]]++;}List<Segment> segments=new ArrayList<>();boolean boundary=false;for(int segment=0;segment<k;segment++){int old=order[segment];double mass=0,squares=0;for(int i=0;i<n;i++){mass+=posterior[i][segment];squares+=posterior[i][segment]*posterior[i][segment];}var equations=best.model().equations().get(old);boundary|=equations.stream().anyMatch(Equation::varianceConstrained);segments.add(new Segment(segment,best.model().proportions()[old],mass/n,best.model().masses()[old],squares>0?mass*mass/squares:Double.NaN,counts[segment],equations));}
        double baseline=baseline(scores,names,edges,options);int q=k-1+k*(work.coefficients+work.responses.size()),referenceQ=k-1+k*(edges.size()+work.responses.size());double ll=best.expectation().logLikelihood(),entropy=0,squares=0;for(double[] row:posterior)for(double value:row){if(value>0)entropy-=value*Math.log(value);squares+=value*value;}double en=k>1?1-entropy/(n*Math.log(k)):Double.NaN,nfi=k>1?(k*squares-n)/(n*(k-1)):Double.NaN,nec=k>1&&ll>baseline?entropy/(ll-baseline):Double.NaN,referenceNec=k>1?entropy/Math.log(k):0;boolean regular=best.converged()&&!boundary;Criteria criteria=new Criteria(q,referenceQ,-2*ll+2*q,-2*ll+3*q,-2*ll+4*q,-2*ll+Math.log(n)*q,-2*ll+(Math.log(n)+1)*q,-2*ll+2*Math.log(Math.log(n))*q,-2*ll+5*Math.log(n)*q,-2*ll+2*referenceQ,-2*ll+Math.log(n)*referenceQ,entropy,en,nfi,nec,referenceNec,baseline,regular);List<String> warnings=new ArrayList<>();if(!best.converged())warnings.add("No converged valid start was available; the selected highest-likelihood candidate is provisional and unsuitable for ordinary model selection.");if(boundary)warnings.add("At least one residual variance is on the configured floor. Information criteria use nominal free-parameter counts; regular mixture approximations may not apply.");if(starts.stream().anyMatch(start->start.failure()!=null))warnings.add("Some starts failed and remain listed; they were not silently replaced.");warnings.add("Mixtures condition on fixed score observations and assume segment-specific Gaussian independent structural errors. Multiple starts reduce, but do not remove, local-optimum risk; segment counts are not selected by a regular likelihood-ratio test.");warnings.add("Standard parameter counts include requested intercepts. The recovered reference criteria omit these intercept parameters; both counts/AIC/BIC are retained. Reference NEC is entropy/log(K), distinct from likelihood-normalized entropy/(LL(K)-LL(1)). One-segment normalized entropy/non-fuzzy indices are undefined in the standard report.");warnings.add("Mixing proportions belong to the final M-step; posterior proportions are separately recomputed from its likelihood. Labels are sorted by fitted mixture proportion; finalToInitial retains the initial-label permutation. Failed-start iteration counts are unavailable, not assumed zero. Centered and global-centered weighted R² have different denominators; no coefficient significance is inferred from memberships.");return new Result(options,n,names,edges,best.start(),best.converged(),ll,segments,posterior,assignments,Arrays.stream(order).mapToInt(Integer::intValue).toArray(),best.initial(),best.trace(),starts,criteria,warnings);
    }
    private static double baseline(double[][] scores,List<String> names,List<PlsSem.Edge> edges,Options supplied){var options=new Options(1,1,2,supplied.tolerance(),supplied.seed(),supplied.intercept(),supplied.varianceFloor(),Math.min(supplied.minimumMass(),scores.length),Initialization.RANDOM_SIMPLEX,Stopping.OBSERVED_LOG_LIKELIHOOD);var work=new Work(scores,names,edges,options);double[][] weights=new double[scores.length][1];for(double[] row:weights)row[0]=1;return work.expectation(work.maximize(weights),weights).logLikelihood();}
}
